package dev.algorithmlearning.api.dashboard.api; import dev.algorithmlearning.api.app.security.CurrentUser; import dev.algorithmlearning.api.dashboard.application.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/dashboard") public class DashboardController {private final DashboardService dashboard;private final CurrentUser user;public DashboardController(DashboardService d,CurrentUser u){dashboard=d;user=u;}@GetMapping DashboardCounts get(){return dashboard.dashboard(user.id());}}
